import type { HTMLAttributes, ReactNode, Ref } from "react";
import "./FeaturedIcon.css";

/**
 * Plate size. The steps are the Sys `size` scale — the same ladder `Avatar`, the colour swatches
 * and the calendar cells sit on — so every square box in the system lines up without any of them
 * naming a pixel value.
 */
type FeaturedIconSize = "x-small" | "small" | "medium" | "large" | "x-large";

/**
 * Which neutral paper the plate is cut from — decided by what it sits ON, not by status.
 *
 * `raised` is near-white and reads as sitting **on top of** a coloured or tinted host (an
 * `Alert`'s status tint). `sunken` is a step darker and reads as **recessed into** a plain white
 * host (a `Dialog`/`Drawer` panel).
 */
type FeaturedIconTone = "raised" | "sunken";

export interface FeaturedIconProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, "className" | "children"> {
  /**
   * Plate size. See {@link FeaturedIconSize}.
   *
   * @default "medium"
   */
  size?: FeaturedIconSize;
  /**
   * Which neutral paper the plate is cut from. See {@link FeaturedIconTone}.
   *
   * @default "raised"
   */
  tone?: FeaturedIconTone;
  /**
   * What the plate holds — an icon glyph, or media.
   *
   * A **glyph** is centred at the size-matched icon step, so pass it at `size="1em"` and let the
   * plate's own token size it. **Media** (an `<img>`) fills the plate edge to edge instead: give
   * it the `sd-featured-icon__media` class and it is cropped to `cover`, the same treatment
   * `Avatar` gives its image.
   */
  children: ReactNode;
  className?: string;
  ref?: Ref<HTMLSpanElement>;
}

/**
 * FeaturedIcon — a rounded neutral plate holding one icon glyph or one image.
 *
 * The "featured icon" treatment: a leading visual that is a *plate* rather than a bare glyph, so
 * it can hold its own beside a title without being sized up. Used by `Alert` today; `Dialog` and
 * `Drawer` grow the same leading visual.
 *
 * Two deliberate restraints:
 * - It sets **no `color`**, so a glyph inherits its host's foreground. That is what lets one
 *   component serve a neutral `Dialog` header and a status-tinted `Alert`, whose glyph must stay
 *   the variant's colour — without a colour axis.
 * - Its **radius holds at the control step for every plate a surface is built around** — the
 *   `medium`/`large`/`x-large` plates all keep `radius.medium`, because the concentric rule
 *   derives a container's radius *from* that one inner-control radius, so it must not move
 *   under the plates that actually sit inside Alert/Dialog/Drawer. Only the two small plates
 *   step down to `radius.small`: at 16-24px the control radius is most of the half-side, so it
 *   reads as a pill rather than a rounded square. Radius therefore tracks `size`, but in two
 *   bands, not five.
 *
 * Distinct from `Avatar`, which is the same box shape but a different contract: Avatar is round,
 * represents a person, requires an `alt`, and falls back to initials. This plate is chrome. They
 * share the Sys `size` scale, not code.
 */
export function FeaturedIcon({
  size = "medium",
  tone = "raised",
  children,
  className,
  ...props
}: FeaturedIconProps) {
  return (
    <span
      {...props}
      data-size={size}
      data-tone={tone}
      className={className ? `sd-featured-icon ${className}` : "sd-featured-icon"}
    >
      {children}
    </span>
  );
}

/* FeaturedIcon.css — .sd-featured-icon
   분류 B: 헤드리스 없이 전부 소유. 기하만 소유하고 전경색은 호스트에서 상속받는다. */

/* A fixed square that centres its content and clips it — the same box Avatar draws, minus the
   circle and the person semantics. `overflow: hidden` is what lets media fill the plate and be
   cropped to the corner; `line-height: 1` keeps a glyph's own leading from padding the box out. */
.sd-featured-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex: 0 0 auto;
  line-height: 1;
}

/* No `color` here on purpose — a glyph inherits the host's foreground, which is what keeps an
   Alert's icon on its variant colour while a Dialog's stays neutral. */
.sd-featured-icon[data-tone="raised"] {
  background: var(--sd-featured-icon-background-raised);
}

.sd-featured-icon[data-tone="sunken"] {
  background: var(--sd-featured-icon-background-sunken);
}

/* Size drives the plate AND the glyph together: the box comes from the Sys `size` ladder, the
   glyph from the `icon` step that reads correctly inside it. The two ladders are deliberately
   NOT 1:1 — `icon` has three steps (12/16/20) against the plate's five, so each glyph step
   serves two plates and the plate grows around it: 12 · 16 · 16 · 20 · 20. The ring of padding
   that leaves (2 · 4 · 8 · 10 · 14) is the point — a bigger plate reads as more emphasis
   through its air, not through a bigger glyph, which is what keeps a 48px featured icon from
   looking like a blown-up 16px one. */
.sd-featured-icon[data-size="x-small"] {
  width: var(--sd-featured-icon-size-x-small);
  height: var(--sd-featured-icon-size-x-small);
  font-size: var(--sd-featured-icon-icon-size-x-small);
  border-radius: var(--sd-featured-icon-radius-x-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-featured-icon[data-size="small"] {
  width: var(--sd-featured-icon-size-small);
  height: var(--sd-featured-icon-size-small);
  font-size: var(--sd-featured-icon-icon-size-small);
  border-radius: var(--sd-featured-icon-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-featured-icon[data-size="medium"] {
  width: var(--sd-featured-icon-size-medium);
  height: var(--sd-featured-icon-size-medium);
  font-size: var(--sd-featured-icon-icon-size-medium);
  border-radius: var(--sd-featured-icon-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-featured-icon[data-size="large"] {
  width: var(--sd-featured-icon-size-large);
  height: var(--sd-featured-icon-size-large);
  font-size: var(--sd-featured-icon-icon-size-large);
  border-radius: var(--sd-featured-icon-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-featured-icon[data-size="x-large"] {
  width: var(--sd-featured-icon-size-x-large);
  height: var(--sd-featured-icon-size-x-large);
  font-size: var(--sd-featured-icon-icon-size-x-large);
  border-radius: var(--sd-featured-icon-radius-x-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* Media fills the plate edge to edge and is cropped, rather than being centred like a glyph —
   the same treatment Avatar gives its image. An opt-in class, because the component cannot tell
   an <img> from an icon component that happens to render one. */
.sd-featured-icon__media {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
